return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ta_LK','project-id-version'=>'babilim-0.1.0-ta_LK-babilim-0.1.0-ta_LK-20261030T033738','pot-creation-date'=>'2026-10-30T06:25:45+00:00','po-revision-date'=>'2026-10-30T06:25:45+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'உங்கள் தளத்தில் ஏற்கனவே நிறுவப்பட்டுள்ள செருகுநிரல்கள் மற்றும் தீம்களுக்கு விடுபட்ட மொழிபெயர்ப்புகளை நிரப்புகிறது.','Translations'=>'மொழிபெயர்ப்புகள்','Babilim Settings'=>'Babilim அமைப்புகள்','Settings'=>'அமைப்புகள்','You are not allowed to do this.'=>'இதைச் செய்ய உங்களுக்கு அனுமதி இல்லை.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'குறைவான கூறுகளைத் தேர்ந்தெடுக்கவும்: ஒரு முறைக்கு அதிகபட்சம் %1$d செயல்பாடுகள் (நீங்கள் %2$d தேர்ந்தெடுத்துள்ளீர்கள்).','That component is not installed on this site, so a translation cannot be requested for it.'=>'அந்தக் கூறு இந்தத் தளத்தில் நிறுவப்படவில்லை, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','Already installed.'=>'ஏற்கனவே நிறுவப்பட்டுள்ளது.','Downloaded and installed.'=>'பதிவிறக்கி நிறுவப்பட்டது.','Babilim has not been enabled for this site yet.'=>'இந்தத் தளத்திற்கு Babilim இன்னும் இயக்கப்படவில்லை.','No build is available to download for this locale.'=>'இந்த மொழிக்குப் பதிவிறக்க எந்தப் பதிப்பும் இல்லை.','Rolled back to the previous build.'=>'முந்தைய பதிப்பிற்கு மீட்டமைக்கப்பட்டது.','Rolled back and reported.'=>'மீட்டமைக்கப்பட்டு புகாரளிக்கப்பட்டது.','Rolled back, but the report could not be sent: %s'=>'மீட்டமைக்கப்பட்டது, ஆனால் புகாரை அனுப்ப முடியவில்லை: %s','Removed.'=>'அகற்றப்பட்டது.','Translation requested.'=>'மொழிபெயர்ப்பு கோரப்பட்டது.','This component was already uploaded. Babilim is checking it now.'=>'இந்தக் கூறு ஏற்கனவே பதிவேற்றப்பட்டுள்ளது. Babilim இப்போது அதைச் சரிபார்க்கிறது.','Upload cancelled.'=>'பதிவேற்றம் ரத்து செய்யப்பட்டது.','Upload complete — translation requested.'=>'பதிவேற்றம் முடிந்தது — மொழிபெயர்ப்பு கோரப்பட்டது.','This component does not declare a version number, so a translation cannot be requested for it.'=>'இந்தக் கூறு பதிப்பு எண்ணை அறிவிக்கவில்லை, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'இந்தக் கூறின் பதிப்பு எண் %d எழுத்துகளை விட நீளமாக உள்ளது, இதை Babilim கையாள முடியாது, எனவே அதற்கு மொழிபெயர்ப்பைக் கோர முடியாது.','A translation cannot be requested for that locale on this site right now.'=>'இந்தத் தளத்தில் அந்த மொழிக்கு இப்போது மொழிபெயர்ப்பைக் கோர முடியாது.','Thank you. Your report was sent.'=>'நன்றி. உங்கள் புகார் அனுப்பப்பட்டது.','This report does not name a valid plugin or theme and locale.'=>'இந்தப் புகார் செல்லுபடியாகும் செருகுநிரல் அல்லது தீம் மற்றும் மொழியைக் குறிப்பிடவில்லை.','Please choose a category for this report.'=>'இந்தப் புகாருக்கு ஒரு வகையைத் தேர்ந்தெடுக்கவும்.','This report is missing a valid build to report against.'=>'இந்தப் புகாருடன் தொடர்புடைய செல்லுபடியான உருவாக்கப் பதிப்பு இல்லை.','This build is not one this site currently knows about for this component/locale.'=>'இந்தக் கூறு/மொழிக்கு இந்தத் தளம் தற்போது அறிந்த பதிப்புகளில் இது ஒன்றல்ல.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" புலம் மிக நீளமாக உள்ளது: அதில் %2$d எழுத்துகள் உள்ளன, வரம்பு %3$d. எதுவும் அனுப்பப்படவில்லை; தயவுசெய்து சுருக்கி மீண்டும் முயலவும்.','Original string'=>'மூலச் சரம்','String context'=>'சரத்தின் சூழல்','Current translation'=>'தற்போதைய மொழிபெயர்ப்பு','Suggested translation'=>'பரிந்துரைக்கப்பட்ட மொழிபெயர்ப்பு','Note (optional)'=>'குறிப்பு (விருப்பத்திற்குரியது)','Where you saw this (optional)'=>'இதை எங்கு பார்த்தீர்கள் (விருப்பத்திற்குரியது)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim ஒத்திசைவு சேவையால் தற்காலிகமாகத் தாமதமாகிறது (வீத வரம்பு); %s க்குப் பிறகு மீண்டும் முயலும்.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'நீங்கள் சேர்த்த மொழி செல்லுபடியாகாது: ll_CC போன்ற WordPress மொழிக் குறியீட்டைப் பயன்படுத்தவும் (எழுத்துகள், இலக்கங்கள், அடிக்கோடு, ஹைபன் அல்லது @, அதிகபட்சம் %d எழுத்துகள்). எதுவும் சேமிக்கப்படவில்லை.','Settings saved.'=>'அமைப்புகள் சேமிக்கப்பட்டன.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'இது இயக்கத்தில் இருந்தால், நிறுவல் நீக்கும்போது இந்தத் தளத்தின் அடையாளமும் அழிக்கப்படும். இந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன் பிறகு தானாக மீட்டெடுக்க முடியாது; அதைத் திரும்பப் பெற %s இல் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும்.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'செருகுநிரல் நீக்கப்படும்போது இந்தத் தளத்தின் அடையாளத்தை அழிக்க Babilim அமைக்கப்பட்டுள்ளது. இந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன் பிறகு தானாக மீட்டெடுக்க முடியாது; நீங்கள் %s இல் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளத்தைத் தக்கவைக்க, Cancel என்பதை அழுத்தி, Babilim அமைப்புகளில் "Delete all Babilim data on uninstall" தேர்வை நீக்கி, மீண்டும் செயலிழக்கச் செய்யவும். எப்படியும் செயலிழக்கச் செய்யவா?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'இந்த நெட்வொர்க்கில் %1$d தளம், செருகுநிரல் நீக்கப்படும்போது அதன் Babilim அடையாளத்தை அழிக்க அமைக்கப்பட்டுள்ளது. அந்தத் தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன் பிறகு தானாக மீட்டெடுக்க முடியாது; நீங்கள் %2$s இல் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளத்தைத் தக்கவைக்க, Cancel என்பதை அழுத்தி, அந்தத் தளத்தின் Babilim அமைப்புகளில் "Delete all Babilim data on uninstall" தேர்வை நீக்கி, மீண்டும் செயலிழக்கச் செய்யவும். எப்படியும் செயலிழக்கச் செய்யவா?' . "\0" . 'இந்த நெட்வொர்க்கில் %1$d தளங்கள், செருகுநிரல் நீக்கப்படும்போது அவற்றின் Babilim அடையாளத்தை அழிக்க அமைக்கப்பட்டுள்ளன. அந்தத் தளங்களுடன் இணைக்கப்பட்ட கட்டண உரிமத்தை அதன் பிறகு தானாக மீட்டெடுக்க முடியாது; நீங்கள் %2$s இல் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளங்களைத் தக்கவைக்க, Cancel என்பதை அழுத்தி, ஒவ்வொரு தளத்தின் Babilim அமைப்புகளிலும் "Delete all Babilim data on uninstall" தேர்வை நீக்கி, மீண்டும் செயலிழக்கச் செய்யவும். எப்படியும் செயலிழக்கச் செய்யவா?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'இந்த நெட்வொர்க்கில் ஒவ்வொன்றாகச் சரிபார்க்க முடியாத அளவுக்கு அதிகமான தளங்கள் உள்ளன, அவற்றில் சில செருகுநிரல் நீக்கப்படும்போது தங்கள் Babilim அடையாளத்தை அழிக்கும்படி அமைக்கப்பட்டிருக்கலாம். அத்தகைய தளத்துடன் இணைக்கப்பட்ட கட்டண உரிமத்தை தானாக மீட்டெடுக்க முடியாது; நீங்கள் %s என்ற முகவரியில் Babilim ஆதரவைத் தொடர்பு கொள்ள வேண்டும். அடையாளங்களைப் பாதுகாக்க, Cancel என்பதை அழுத்தி, ஒவ்வொரு தளத்தின் Babilim அமைப்புகளிலும் "நீக்கும்போது அனைத்து Babilim தரவையும் அழிக்கவும்" என்பதைத் தேர்வுநீக்கி, மீண்டும் செயலிழக்கச் செய்யவும். எப்படியும் செயலிழக்கச் செய்யவா?','Open Babilim settings'=>'Babilim அமைப்புகளைத் திறக்கவும்','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim இந்தத் தளத்தைச் சரிபார்க்க முடியவில்லை, எனவே எதுவும் பதிவிறக்கப்படவோ நிறுவப்படவோ இல்லை.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'சேவையால் உங்கள் தளத்தை அணுக முடியவில்லை. ஃபயர்வால், பாதுகாப்புச் செருகுநிரல் அல்லது ஹோஸ்ட் விதி அந்தக் கோரிக்கையைத் தடுக்கக்கூடும்; /wp-json/babilim/v1/challenge க்கான கோரிக்கைகளை அனுமதிக்கவும்.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'உங்கள் தளம் பதிலளிக்க அதிக நேரம் எடுத்தது. பின்னர் மீண்டும் முயற்சிக்கவும், உங்கள் ஹோஸ்ட் மிகவும் மெதுவாகவோ அதிகச் சுமையுடனோ இல்லை என்பதைச் சரிபார்க்கவும்.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'உங்கள் தளம் பதிலளித்தது, ஆனால் எதிர்பார்த்த பதிலுடன் அல்ல. REST API வேறொரு செருகுநிரலால் மாற்றி எழுதப்பட்டிருக்கலாம், அல்லது அந்த எண்ட்பாயிண்ட் கேச் செய்யப்பட்டிருக்கலாம்; /wp-json/babilim/v1/challenge ஐ கேச்சிங் மற்றும் மாற்றி எழுதுதலிலிருந்து விலக்கவும்.','Please check that your site can be reached from the internet, then try again.'=>'உங்கள் தளத்தை இணையத்திலிருந்து அணுக முடியும் என்பதைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.','Re-verify'=>'மீண்டும் சரிபார்','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'இந்தத் தளம் ஒரே ஒத்திசைவில் சேவை ஏற்கும் அளவை மீறுகிறது, எனவே சில உருப்படிகள் விடப்பட்டன: %1$d கூறுகள் மற்றும் %2$d மொழிகள்.','This site is verified.'=>'இந்தத் தளம் சரிபார்க்கப்பட்டது.','Registration restarted.'=>'பதிவு மீண்டும் தொடங்கப்பட்டது.','Sync complete.'=>'ஒத்திசைவு முடிந்தது.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim இந்தத் தளத்தை இயக்கிச் சரிபார்க்கிறது… இந்தப் பக்கத்தை மீண்டும் ஏற்றவும் அல்லது திட்டமிட்ட சரிபார்ப்பு முடியும் வரை காத்திருக்கவும்.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim இயக்குவதை முடிக்க முடியவில்லை (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'ஒரு நேரத்தில் ஒரு PHP கோரிக்கையை மட்டுமே வழங்கும் ஹோஸ்ட்டால் இந்தப் படியை முடிக்க முடியாது.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim இயக்கப்பட்டது: இந்தத் தளம் சரிபார்க்கப்பட்டது, %d கூறு கண்டறியப்பட்டது.' . "\0" . 'Babilim இயக்கப்பட்டது: இந்தத் தளம் சரிபார்க்கப்பட்டது, %d கூறுகள் கண்டறியப்பட்டன.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim முடக்கப்பட்டுள்ளது. இனி எதுவும் அனுப்பப்படாது; ஏற்கெனவே நிறுவப்பட்ட மொழிபெயர்ப்புகள் தொடர்ந்து செயல்படும்.','Supplementary translation index rebuilt.'=>'துணை மொழிபெயர்ப்பு குறியீட்டு அட்டவணை மீண்டும் உருவாக்கப்பட்டது.','Sweep complete: %d file deleted.'=>'துப்புரவு முடிந்தது: %d கோப்பு நீக்கப்பட்டது.' . "\0" . 'துப்புரவு முடிந்தது: %d கோப்புகள் நீக்கப்பட்டன.','Removed %d installed component.'=>'நிறுவப்பட்ட %d கூறு அகற்றப்பட்டது.' . "\0" . 'நிறுவப்பட்ட %d கூறுகள் அகற்றப்பட்டன.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'தானியங்கி நிறுவல்கள் இப்போது முடக்கப்பட்டுள்ளன; தேவைப்பட்டால் அமைப்புகளில் மீண்டும் இயக்கவும்.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'உங்கள் மொழிக்கு மொழிபெயர்ப்பு இல்லாத இந்தத் தளத்தின் செருகுநிரல்கள் மற்றும் தீம்களை Babilim கண்டறிந்து, ஒவ்வொன்றுக்கும் ஒன்றை நிறுவுகிறது.','Languages found on this site: %s.'=>'இந்தத் தளத்தில் கண்டறியப்பட்ட மொழிகள்: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'கிடைக்கும் மொழிபெயர்ப்புகளை ஒரே கிளிக்கில் நிறுவலாம், இல்லாதவற்றைக் கோரலாம். அதன் பிறகு, புதிய மொழிபெயர்ப்புகளும் புதுப்பிப்புகளும் தானாக நிறுவப்படும் (இலவசத் திட்டத்தில், ஏற்கெனவே இலவச இடத்தைப் பயன்படுத்தும் செருகுநிரல்கள் மற்றும் தீம்களுக்கு மட்டும்).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'இலவசத் திட்டம் குறிப்பிட்ட எண்ணிக்கையிலான செருகுநிரல்கள் மற்றும் தீம்களை உள்ளடக்கும்; Babilim ஐ இயக்கிய பிறகு உங்கள் ஒதுக்கீடு அமைப்புகளில் காட்டப்படும்.','What is sent when you enable Babilim'=>'Babilim ஐ இயக்கும்போது அனுப்பப்படுபவை','Enabling…'=>'இயக்குகிறது…','Enable Babilim'=>'Babilim ஐ இயக்கு','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Enable என்பதைக் கிளிக் செய்வதன் மூலம், மேலே பட்டியலிடப்பட்ட தகவலை Babilim க்கு அனுப்ப ஒப்புக்கொள்கிறீர்கள்.','Check again now'=>'இப்போது மீண்டும் சரிபார்','Babilim installed %d translation automatically since your last visit.'=>'உங்கள் கடைசி வருகைக்குப் பிறகு Babilim %d மொழிபெயர்ப்பைத் தானாக நிறுவியது.' . "\0" . 'உங்கள் கடைசி வருகைக்குப் பிறகு Babilim %d மொழிபெயர்ப்புகளைத் தானாக நிறுவியது.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim இந்தத் தளத்தை இயக்கிச் சரிபார்க்கிறது… (கடைசி முயற்சி: %s)','Check again'=>'மீண்டும் சரிபார்','No components synced yet.'=>'இதுவரை கூறுகள் எதுவும் ஒத்திசைக்கப்படவில்லை.','%d succeeded'=>'%d வெற்றி' . "\0" . '%d வெற்றி','%d skipped'=>'%d தவிர்க்கப்பட்டது' . "\0" . '%d தவிர்க்கப்பட்டன','%d failed'=>'%d தோல்வி' . "\0" . '%d தோல்வி','%d not yet tried'=>'%d இன்னும் முயற்சிக்கப்படவில்லை' . "\0" . '%d இன்னும் முயற்சிக்கப்படவில்லை','Bulk %s:'=>'மொத்த %s:','%1$s nothing to do.'=>'%1$s செய்ய எதுவும் இல்லை.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'தொடர்கிறது…','Continue next batch (%d left)'=>'அடுத்த தொகுதியைத் தொடரவும் (%d மீதமுள்ளன)','Search components'=>'கூறுகளைத் தேடு','These are the languages this site uses. You can change them in %s.'=>'இந்தத் தளம் பயன்படுத்தும் மொழிகள் இவை. நீங்கள் அவற்றை %s இல் மாற்றலாம்.','Upload this component?'=>'இந்தக் கூறைப் பதிவேற்றவா?','There is no upload waiting for confirmation.'=>'உறுதிப்படுத்தலுக்காகக் காத்திருக்கும் பதிவேற்றம் எதுவும் இல்லை.','Back'=>'பின்செல்','To translate this component, Babilim needs its source.'=>'இந்தக் கூறை மொழிபெயர்க்க, Babilim-க்கு அதன் மூலம் தேவை.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (பதிப்பு %2$s) இன் முழு செருகுநிரல் அல்லது தீம் கோப்பகமும் Babilim-க்குப் பதிவேற்றப்படும்.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'அந்தக் கோப்பகத்தில் விசைகள், பதிவுகள் அல்லது வாடிக்கையாளர் தரவு இருந்தால், அவையும் பதிவேற்றப்படும். சேவை பொதுவாக இரகசியத் தகவல்களைக் கொண்டிருக்கும் கோப்புகளை (உள்ளமைவு, சூழல், தரவுத்தள டம்ப்கள், பதிவுகள், விசைகள்) நீக்குகிறது. ஆனால் அத்தகைய கோப்புகள் அனைத்தையும் கண்டறியும் என உறுதியளிக்க முடியாது.','The upload is kept until you ask Babilim to delete it.'=>'நீங்கள் Babilim-இடம் நீக்கக் கோரும் வரை பதிவேற்றம் வைத்திருக்கப்படும்.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'இது சேவையின் ஹோஸ்டிங் வழங்குநரால் சேமிக்கப்பட்டு, மொழிபெயர்ப்பை உருவாக்க AI மாதிரிகளால் செயலாக்கப்படும்.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'மூல உரையும் அதிலிருந்து உருவாக்கப்பட்ட மொழிபெயர்ப்புகளும் அதே பதிப்பை நிறுவும் பிற தளங்களுக்கு வழங்கப்படும்.','By continuing you confirm that you have the right to upload this component.'=>'தொடர்வதன் மூலம், இந்தக் கூறைப் பதிவேற்ற உங்களுக்கு உரிமை உள்ளது என்பதை உறுதிப்படுத்துகிறீர்கள்.','Upload and request'=>'பதிவேற்றிக் கோரு','Uploading…'=>'பதிவேற்றுகிறது…','Cancel'=>'ரத்துசெய்','Uploading'=>'பதிவேற்றுகிறது','There is no upload in progress.'=>'நடப்பில் உள்ள பதிவேற்றம் எதுவும் இல்லை.','Uploading part %1$d of %2$d…'=>'பகுதி %1$d / %2$d பதிவேற்றுகிறது…','Continue'=>'தொடர்','Confirm'=>'உறுதிப்படுத்து','Remove'=>'அகற்று','Roll back'=>'முந்தைய நிலைக்கு மீட்டமை','Nothing to confirm.'=>'உறுதிப்படுத்த எதுவும் இல்லை.','Choose a language'=>'மொழியைத் தேர்ந்தெடுக்கவும்','Roll back and report'=>'முந்தைய நிலைக்கு மீட்டமைத்துப் புகாரளி','Report a problem'=>'சிக்கலைப் புகாரளி','Nothing to choose.'=>'தேர்ந்தெடுக்க எதுவும் இல்லை.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. மொழியைத் தேர்ந்தெடுக்கவும்.','Supplementary translations'=>'துணை மொழிபெயர்ப்புகள்','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ஒவ்வொரு மொழிக்கூறுக்குமான பகிரப்பட்ட இயல்புநிலை-டொமைன் துணைத் தொகுப்பில் ஒவ்வொரு கூறின் சொந்தப் பங்களிப்பு.','Component'=>'கூறு','Language'=>'மொழி','Included in index'=>'அட்டவணையில் சேர்க்கப்பட்டது','Entries'=>'உள்ளீடுகள்','Conflicting keys'=>'முரண்படும் விசைகள்','Yes'=>'ஆம்','No — component inactive'=>'இல்லை — கூறு செயலில் இல்லை','No — installed version differs from the active one'=>'இல்லை — நிறுவப்பட்ட பதிப்பு செயலில் உள்ளதிலிருந்து வேறுபடுகிறது','No — component removed'=>'இல்லை — கூறு நீக்கப்பட்டது','No'=>'இல்லை','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'இதை நெட்வொர்க் நிர்வாகி மட்டுமே செய்ய முடியும், ஏனெனில் இது இந்த நெட்வொர்க்கில் உள்ள அனைத்து தளங்களும் பகிரும் மொழிபெயர்ப்புக் கோப்புகளை மாற்றுகிறது.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'இந்தத் தளத்தைச் சரிபார்த்து முடிக்க Babilim-ஆல் இயலவில்லை (சேவை மீண்டும் தளத்தை அணுக முடியவில்லை). பதிவு இடைநிறுத்தப்பட்டுள்ளது.','This site already has an active registration that can no longer be recovered automatically.'=>'இந்தத் தளத்திற்கு ஏற்கனவே செயலில் உள்ள பதிவு உள்ளது; அதைத் தானாக மீட்டெடுக்க இனி இயலாது.','Restart registration'=>'பதிவை மீண்டும் தொடங்கவும்','Babilim settings'=>'Babilim அமைப்புகள்','General'=>'பொது','Advanced'=>'மேம்பட்டவை','Languages'=>'மொழிகள்','Automatic installs'=>'தானியங்கி நிறுவல்கள்','Install available translations automatically'=>'கிடைக்கும் மொழிபெயர்ப்புகளைத் தானாக நிறுவவும்','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'இலவசத் திட்டத்தில், உங்கள் இலவச இடங்களில் ஒன்றை ஏற்கனவே பயன்படுத்தும் கூறுகள் மட்டுமே தானாக நிறுவப்படும்; எனவே புதிய இடம் எதுவும் எடுக்கப்படாது.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'இந்தத் தளம் பல்தள நெட்வொர்க்கின் ஒரு பகுதியாகும்; இது புதிய மொழிபெயர்ப்புகளைத் தானாக நிறுவாது. ஏற்கனவே நிறுவப்பட்ட மொழிபெயர்ப்புகள் தொடர்ந்து புதுப்பிக்கப்படும்.','Custom overrides'=>'தனிப்பயன் மேலெழுதல்கள்','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'அனைத்தையும் அழிக்கும்போது அல்லது இந்த செருகுநிரலை நீக்கும்போது எனது சொந்த மொழிபெயர்ப்பு மேலெழுதல்களை வைத்திருக்கவும்.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'நீங்கள் %s இல் வைக்கும் மொழிபெயர்ப்புக் கோப்புகள் எப்போதும் Babilim கோப்புகளை விட முன்னுரிமை பெறும். இதைத் தேர்வுநீக்காவிட்டால் அவை வைத்திருக்கப்படும்.','Uninstall'=>'நீக்கம்','Delete all Babilim data on uninstall'=>'நீக்கும்போது அனைத்து Babilim தரவையும் அழிக்கவும்','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'இயல்பாக முடக்கப்பட்டுள்ளது: செருகுநிரலை நீக்கினாலும் இந்தத் தளத்தின் அடையாளம் வைத்திருக்கப்படும்; எனவே மீண்டும் நிறுவும்போது அதை மீண்டும் பயன்படுத்தலாம்.','Account'=>'கணக்கு','Save changes'=>'மாற்றங்களைச் சேமி','Disable Babilim'=>'Babilim-ஐ முடக்கு','Installed translations are kept, but no further checks or downloads will run.'=>'நிறுவப்பட்ட மொழிபெயர்ப்புகள் வைத்திருக்கப்படும், ஆனால் மேலும் சரிபார்ப்புகளோ பதிவிறக்கங்களோ நடைபெறாது.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim-ஐ முடக்கவா? நிறுவப்பட்ட மொழிபெயர்ப்புகள் வைத்திருக்கப்படும், ஆனால் மேலும் சரிபார்ப்புகளோ பதிவிறக்கங்களோ நடைபெறாது.','This site is not registered with Babilim yet.'=>'இந்தத் தளம் இன்னும் Babilim-இல் பதிவு செய்யப்படவில்லை.','This site is already licensed. Reload the page.'=>'இந்தத் தளத்திற்கு ஏற்கனவே உரிமம் உள்ளது. பக்கத்தை மீண்டும் ஏற்றவும்.','Checkout is not available for this site right now.'=>'இந்தத் தளத்திற்கு இப்போது பணம் செலுத்தும் பக்கம் கிடைக்கவில்லை.','Could not start checkout: %s'=>'பணம் செலுத்தும் பக்கத்தைத் தொடங்க இயலவில்லை: %s','Babilim is not enabled.'=>'Babilim இயக்கப்படவில்லை.','Not registered yet'=>'இன்னும் பதிவு செய்யப்படவில்லை','Not verified'=>'சரிபார்க்கப்படவில்லை','Verified'=>'சரிபார்க்கப்பட்டது','Status'=>'நிலை','Licensed'=>'உரிமம் பெற்றது','Partner'=>'கூட்டாளர்','Free'=>'இலவசம்','License'=>'உரிமம்','Upgrade this site'=>'இந்தத் தளத்தை மேம்படுத்து','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'இந்தத் தளத்திற்கான ஒருமுறை கொள்முதல்: %1$s %2$s. எதிர்கால மொழிபெயர்ப்பு புதுப்பிப்புகள் அனைத்தும் இதில் அடங்கும். கட்டணம் புதிய தாவலில் Paddle மூலம் கையாளப்படும்.','This issues a new restore code and the previous one stops working. Continue?'=>'இது புதிய மீட்பு குறியீட்டை வழங்கும்; முந்தையது செயல்படாது. தொடரவா?','Show a new restore code'=>'புதிய மீட்பு குறியீட்டைக் காட்டு','rc_…'=>'rc_…','Restore code'=>'மீட்பு குறியீடு','Restore purchase'=>'கொள்முதலை மீட்டெடு','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'இந்தத் டொமைனுக்கு முன்பு உரிமம் வாங்கினீர்களா? பணம் செலுத்தும் பக்கத்தில் பெற்ற மீட்பு குறியீட்டை உள்ளிடவும்.','That does not look like a restore code.'=>'இது மீட்பு குறியீடு போலத் தெரியவில்லை.','This restore code was not recognised for this site.'=>'இந்த மீட்பு குறியீடு இந்தத் தளத்திற்கு அடையாளம் காணப்படவில்லை.','Too many attempts. Try again tomorrow.'=>'அதிக முயற்சிகள். நாளை மீண்டும் முயலவும்.','This site must be verified first.'=>'இந்தத் தளம் முதலில் சரிபார்க்கப்பட வேண்டும்.','Could not restore the purchase: %s'=>'கொள்முதலை மீட்டெடுக்க முடியவில்லை: %s','Purchase restored. This site is now licensed.'=>'கொள்முதல் மீட்டெடுக்கப்பட்டது. இந்தத் தளம் இப்போது உரிமம் பெற்றுள்ளது.','This site has no purchase to show a code for.'=>'குறியீட்டைக் காட்ட இந்தத் தளத்தில் கொள்முதல் எதுவும் இல்லை.','Could not show a new restore code: %s'=>'புதிய மீட்பு குறியீட்டைக் காட்ட முடியவில்லை: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'உங்கள் புதிய மீட்பு குறியீடு: %s. இதைப் பாதுகாப்பான இடத்தில் வைத்திருங்கள் — முந்தைய குறியீடு இனி செயல்படாது.','What is sent when Babilim checks this site'=>'Babilim இந்தத் தளத்தைச் சரிபார்க்கும்போது அனுப்பப்படுவது','(detected)'=>'(கண்டறியப்பட்டது)','No language is managed yet.'=>'இன்னும் எந்த மொழியும் நிர்வகிக்கப்படவில்லை.','Babilim adds translations for every language checked here.'=>'இங்கே தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு மொழிக்கும் Babilim மொழிபெயர்ப்புகளைச் சேர்க்கும்.','Add another language'=>'மற்றொரு மொழியைச் சேர்','Choose a language…'=>'மொழியைத் தேர்ந்தெடுக்கவும்…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'சேவையிலிருந்து முழு WordPress.org மொழிப் பட்டியலை ஏற்ற முடியவில்லை, எனவே இப்போது வேறு மொழியைச் சேர்க்க முடியாது.','Theme'=>'தீம்','Plugin'=>'செருகுநிரல்','Free quota'=>'இலவச ஒதுக்கீடு','Downloads: %1$d/%2$d (%3$s)'=>'பதிவிறக்கங்கள்: %1$d/%2$d (%3$s)','Supplementary translation index'=>'துணை மொழிபெயர்ப்பு குறியீட்டு அட்டவணை','Built'=>'உருவாக்கப்பட்டது','Included'=>'சேர்க்கப்பட்டவை','Excluded'=>'விலக்கப்பட்டவை','Already in WordPress core'=>'ஏற்கனவே WordPress மையத்தில் உள்ளது','Supplementary translation maintenance'=>'துணை மொழிபெயர்ப்பு பராமரிப்பு','Maintenance status is not available right now.'=>'பராமரிப்பு நிலை இப்போது கிடைக்கவில்லை.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s அன்று தூய்மைப்படுத்தல் இடைநிறுத்தப்பட்டது: %2$s. எதுவும் நீக்கப்படவில்லை.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'கடைசி தூய்மைப்படுத்தல் %1$s அன்று: %2$d புதிதாகக் குறிக்கப்பட்டன, %3$d கோப்பு(கள்) நீக்கப்பட்டன, %4$d பதிவு(கள்) அகற்றப்பட்டன.','No cleanup has run yet.'=>'இதுவரை எந்த தூய்மைப்படுத்தலும் இயங்கவில்லை.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s அன்று translation-index எழுதும் செயல்பாடு (%2$s) வேறொரு கோரிக்கையுடன் முரண்பட்டதால் அது பயன்படுத்தப்படவில்லை; மிகச் சமீபத்திய பதிப்பு தக்கவைக்கப்பட்டது.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s அன்று translation-index எழுதும் செயல்பாட்டை (%2$s) முடிக்க முடியவில்லை; அது பயன்படுத்தப்படவில்லை (%3$s).','Maintenance'=>'பராமரிப்பு','Rebuild index now'=>'இப்போது சுட்டியை மீண்டும் உருவாக்கு','Sweep now'=>'இப்போது தூய்மைப்படுத்து','Danger zone'=>'ஆபத்தான பகுதி','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'இந்தத் தளத்தில் உள்ள ஒவ்வொரு செருகுநிரலுக்கும் தீமுக்கும் Babilim நிறுவிய அனைத்து மொழிக் கோப்புகளையும் அகற்றும்.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim நிறுவிய அனைத்தையும் அகற்றவா? இந்தத் தளத்தில் உள்ள ஒவ்வொரு செருகுநிரலுக்கும் தீமுக்கும் அது நிறுவிய அனைத்து மொழிக் கோப்புகளும் நீக்கப்படும்.','Remove everything Babilim installed'=>'Babilim நிறுவிய அனைத்தையும் அகற்று','This string is too long to be sent as a report, so no report form is offered for it.'=>'இந்தச் சரம் அறிக்கையாக அனுப்ப முடியாத அளவு நீளமானது, எனவே இதற்கு அறிக்கைப் படிவம் வழங்கப்படவில்லை.','Category'=>'வகை','Choose a category…'=>'ஒரு வகையைத் தேர்ந்தெடுக்கவும்…','Roll back and send report'=>'முந்தைய நிலைக்கு மீட்டமைத்து அறிக்கையை அனுப்பு','Send report'=>'அறிக்கையை அனுப்பு','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'இந்தக் கூறின் சில உரைகள் அதன் ஆசிரியரால் நேரடியாகக் குறியீட்டில் எழுதப்பட்டுள்ளன; அவற்றை மொழிப் பொதியால் மொழிபெயர்க்க முடியாது.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'தீமுடன் இணைக்கப்பட்டது','Bundled with the plugin'=>'செருகுநிரலுடன் இணைக்கப்பட்டது','Upload was not accepted'=>'பதிவேற்றம் ஏற்றுக்கொள்ளப்படவில்லை','Upload expired before it finished'=>'பதிவேற்றம் முடிவதற்குள் காலாவதியானது','No translation'=>'மொழிபெயர்ப்பு இல்லை','Upload in progress — continue or cancel'=>'பதிவேற்றம் நடைபெறுகிறது — தொடரவும் அல்லது ரத்துசெய்யவும்','Scheduled, waiting to be processed'=>'திட்டமிடப்பட்டது, செயலாக்கத்திற்காகக் காத்திருக்கிறது','Translating…'=>'மொழிபெயர்க்கிறது…','Translation failed'=>'மொழிபெயர்ப்பு தோல்வியடைந்தது','Free quota used'=>'இலவச ஒதுக்கீடு பயன்படுத்தப்பட்டது','Needs a paid license'=>'கட்டண உரிமம் தேவை','Not supported'=>'ஆதரிக்கப்படவில்லை','Status unknown'=>'நிலை தெரியவில்லை','translation statusInstalled'=>'நிறுவப்பட்டது','Update available'=>'புதுப்பிப்பு உள்ளது','Removed after a failed integrity check'=>'ஒருமைப்பாட்டுச் சரிபார்ப்பு தோல்வியடைந்ததால் நீக்கப்பட்டது','Installed · built for %s, new version scheduled'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பு திட்டமிடப்பட்டுள்ளது','Installed · built for a different version, new version scheduled'=>'நிறுவப்பட்டது · வேறொரு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பு திட்டமிடப்பட்டுள்ளது','Installed · built for %s, translating the new version…'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பை மொழிபெயர்க்கிறது…','Installed · built for a different version, translating the new version…'=>'நிறுவப்பட்டது · வேறொரு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பை மொழிபெயர்க்கிறது…','Installed · built for %1$s, this site has %2$s'=>'நிறுவப்பட்டது · %1$s க்காக உருவாக்கப்பட்டது, இந்தத் தளத்தில் %2$s உள்ளது','Installed · built for %s'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது','Installed · built for a different version'=>'நிறுவப்பட்டது · வேறொரு பதிப்பிற்காக உருவாக்கப்பட்டது','Installed · built for %s, new version failed'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்பு தோல்வியடைந்தது','Installed · built for a different version, new version failed'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்பு தோல்வியடைந்தது','Installed · built for %s, new version needs a paid license'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, புதிய பதிப்புக்கு கட்டண உரிமம் தேவை','Installed · built for a different version, new version needs a paid license'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, புதிய பதிப்புக்கு கட்டண உரிமம் தேவை','Installed · built for %s, free quota used'=>'நிறுவப்பட்டது · %s க்காக உருவாக்கப்பட்டது, இலவச ஒதுக்கீடு பயன்படுத்தப்பட்டுவிட்டது','Installed · built for a different version, free quota used'=>'நிறுவப்பட்டது · வேறு பதிப்பிற்காக உருவாக்கப்பட்டது, இலவச ஒதுக்கீடு பயன்படுத்தப்பட்டுவிட்டது','translation statusAvailable'=>'கிடைக்கிறது','Installed · %s'=>'நிறுவப்பட்டது · %s','Available · %s'=>'கிடைக்கிறது · %s','Update'=>'புதுப்பி','Download'=>'பதிவிறக்கு','Updating…'=>'புதுப்பிக்கிறது…','Downloading…'=>'பதிவிறக்குகிறது…','Retry request'=>'கோரிக்கையை மீண்டும் முயற்சி','Request newer translation'=>'புதிய மொழிபெயர்ப்பைக் கோரு','Request translation'=>'மொழிபெயர்ப்பைக் கோரு','Requesting…'=>'கோருகிறது…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'மொழிபெயர்ப்பைக் கோருவது உங்கள் இலவச இடங்களில் ஒன்றைப் பயன்படுத்தும்; இந்தக் கூறு ஏற்கெனவே ஒன்றைப் பயன்படுத்தினால் தவிர. தோல்வியடைந்த மொழிபெயர்ப்பு அந்த இடத்தைத் திருப்பித் தராது.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'இந்தக் கூறு உங்கள் இலவச இடங்களில் ஒன்றை இன்னும் பயன்படுத்தவில்லை என்றால், மொழிபெயர்ப்பைக் கோருவது ஒன்றைப் பயன்படுத்தும். தோல்வியடைந்த மொழிபெயர்ப்பு அந்த இடத்தைத் திருப்பித் தராது. தொடரவா?','No plugins or themes found.'=>'செருகுநிரல்கள் அல்லது தீம்கள் எதுவும் கிடைக்கவில்லை.','Clear filters'=>'வடிகட்டிகளை அழி','No components match these filters. %s'=>'இந்த வடிகட்டிகளுக்குப் பொருந்தும் கூறுகள் எதுவும் இல்லை. %s','Select all'=>'அனைத்தையும் தேர்ந்தெடு','All'=>'அனைத்தும்','Available'=>'கிடைக்கிறது','Updates'=>'புதுப்பிப்புகள்','Requestable'=>'கோரக்கூடியது','Installed'=>'நிறுவப்பட்டது','Plugins'=>'செருகுநிரல்கள்','Themes'=>'தீம்கள்','All languages'=>'அனைத்து மொழிகளும்','%d to install'=>'%d நிறுவப்பட உள்ளது' . "\0" . '%d நிறுவப்பட உள்ளன','Language:'=>'மொழி:','Bulk actions apply to every matching language of each selected component.'=>'மொத்தச் செயல்கள், தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு கூறின் பொருந்தும் அனைத்து மொழிகளுக்கும் பொருந்தும்.','Bulk actions apply only to the selected language of each selected component.'=>'மொத்தச் செயல்கள், தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு கூறின் தேர்ந்தெடுக்கப்பட்ட மொழிக்கு மட்டுமே பொருந்தும்.','Version %s'=>'பதிப்பு %s','Theme · %s'=>'தீம் · %s','Plugin · %s'=>'செருகுநிரல் · %s','Remove the %2$s translation of %1$s from this site?'=>'%1$s இன் %2$s மொழிபெயர்ப்பை இந்தத் தளத்திலிருந்து அகற்றவா?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s இன் %2$s மொழிபெயர்ப்பை முந்தைய கட்டமைப்புப் பதிப்புக்கு மீட்டமைக்கவா?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'பதிவுச் சவால் எதிர்பார்க்கப்பட்ட வடிவத்தில் இல்லை.','That is not a valid build identifier.'=>'இது செல்லுபடியாகும் உருவாக்க அடையாளங்காட்டி அல்ல.','Refusing to write outside the Babilim language-file directory.'=>'Babilim மொழிக் கோப்பு அடைவுக்கு வெளியே எழுத மறுக்கப்படுகிறது.','Could not write the downloaded package to disk.'=>'பதிவிறக்கிய தொகுப்பை வட்டில் எழுத முடியவில்லை.','Unexpected HTTP %d response.'=>'எதிர்பாராத HTTP %d பதில்.','This site\'s URL, so the service can verify you own it.'=>'இந்தத் தளத்தின் URL, இதனால் இதன் உரிமையாளர் நீங்கள்தான் என்பதை சேவை சரிபார்க்க முடியும்.','Your WordPress version, to serve compatible translation files.'=>'உங்கள் WordPress பதிப்பு, இணக்கமான மொழிபெயர்ப்புக் கோப்புகளை வழங்குவதற்காக.','Your PHP version, for compatibility.'=>'உங்கள் PHP பதிப்பு, இணக்கத்தன்மைக்காக.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'இந்தச் செருகுநிரலின் சொந்தப் பதிப்பு, இது மிகவும் பழையதாக இருந்து சேவையுடன் தொடர்பு கொள்ள முடியாவிட்டால் புதுப்பிக்கச் சொல்வதற்காக.','This site\'s configured locale.'=>'இந்தத் தளத்தில் கட்டமைக்கப்பட்ட மொழிப்பகுதி.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'இந்தத் தளத்தில் பயன்பாட்டில் உள்ள ஒவ்வொரு மொழிப்பகுதியும் (தளத்தின் மொழிப்பகுதி, நிறுவப்பட்ட மொழித் தொகுப்புகள், பயனர் மொழிப்பகுதிகள், நீங்கள் கைமுறையாகச் சேர்த்தவை). எந்த மொழிப்பகுதியும் மற்றொன்றிலிருந்து வேறுபடுத்தி நடத்தப்படுவதில்லை.','(a public key generated for this site)'=>'(இந்தத் தளத்திற்காக உருவாக்கப்பட்ட பொதுத் திறவு)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'இந்தத் தளத்தின் நிறுவல் பொதுத் திறவு, கோரிக்கைகள் உண்மையிலேயே இந்தத் தளத்திலிருந்து வருகின்றன என்பதை நிரூபிக்கப் பயன்படுகிறது. பொதுப் பாதி மட்டுமே அனுப்பப்படும்.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'நிறுவப்பட்ட ஒவ்வொரு செருகுநிரல்/தீம்: அதன் ஸ்லக், பதிப்பு, உரை டொமைன்(கள்), அது wp.org பட்டியலா என்பது, அதனுடன் வரும் மொழிப்பகுதிகள், மற்றும் எந்த மொழிப்பகுதிகளுக்கு Babilim மொழிபெயர்ப்பை ஏற்கனவே நிறுவியுள்ளீர்கள் என்பது.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'WordPress.org இல் இல்லாத செருகுநிரல் அல்லது தீமுக்கான பதிவேற்றத்தை நீங்கள் உறுதிப்படுத்தும்போது மட்டும்: அந்தக் கூறின் முழு அடைவும் ஒரு zip ஆக.','(generic codes and coordinates only)'=>'(பொதுக் குறியீடுகளும் ஆயத்தொலைவுகளும் மட்டும்)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'நிலுவையில் உள்ள 20 வரையிலான கண்டறிதல் நிகழ்வுகள் (எ.கா. ஒருமைப்பாட்டுச் சரிபார்ப்பில் தோல்வியடைந்த கோப்பு), ஒவ்வொன்றும் ஒரு குறியீடு, கூறு, மொழிப்பகுதி மட்டுமே; எந்தச் சரத்து உள்ளடக்கமோ மொழிபெயர்க்கப்பட்ட உரையோ ஒருபோதும் இல்லை.','Unsafe locale: %s'=>'பாதுகாப்பற்ற மொழிப்பகுதி: %s','Manifest unavailable: %s'=>'மேனிஃபெஸ்ட் கிடைக்கவில்லை: %s','Could not determine active components; the existing merged index was left unchanged.'=>'செயலில் உள்ள கூறுகளைத் தீர்மானிக்க முடியவில்லை; ஏற்கனவே உள்ள ஒன்றிணைந்த குறியீடு மாற்றப்படாமல் விடப்பட்டது.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'நிறுவப்பட்ட செருகுநிரல்கள்/தீம்களைத் தீர்மானிக்க முடியவில்லை; துடைப்பு தவிர்க்கப்பட்டது, எதுவும் நீக்கப்படவில்லை.','Sweep aborted without orphaning anything: %s.'=>'எதையும் அனாதையாக்காமல் துடைப்பு நிறுத்தப்பட்டது: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'தூய்மைப்படுத்தல் இயங்கியது, ஆனால் அதன் சில மாற்றங்களை மொழிபெயர்ப்புக் குறியீட்டில் பதிவு செய்ய முடியவில்லை; அடுத்த தூய்மைப்படுத்தல் மீண்டும் முயலும்.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' க்கான ஒன்றிணைந்த சுட்டி மீண்டும் உருவாக்கப்பட்டது, ஆனால் மொழிபெயர்ப்புச் சுட்டியால் அதைப் பதிவு செய்ய முடியவில்லை; அடுத்த மறுஉருவாக்கத்தின்போது மீண்டும் முயற்சிக்கப்படும்.','Could not write the staged merged index.'=>'தயார்நிலையில் உள்ள ஒன்றிணைந்த சுட்டியை எழுத முடியவில்லை.','Re-parsed entry count did not match the built index.'=>'மீண்டும் பகுப்பாய்வு செய்யப்பட்ட உள்ளீடுகளின் எண்ணிக்கை உருவாக்கப்பட்ட சுட்டியுடன் பொருந்தவில்லை.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' க்கான ஒன்றிணைந்த சுட்டியை உரிய இடத்திற்கு நகர்த்த முடியவில்லை; முன்னர் வழங்கப்பட்ட சுட்டி (இருந்தால்) பாதியளவு புதுப்பிக்கப்பட்ட நிலையில் விடப்படாமல் நீக்கப்பட்டது. அடுத்த வெற்றிகரமான மறுஉருவாக்கம் வரை இந்த மொழிப்பகுதிக்கு default-டொமைன் துணை எதுவும் வழங்கப்படாது.','Could not open zip: %s'=>'zip ஐத் திறக்க முடியவில்லை: %s','Zip has no manifest.json.'=>'Zip இல் manifest.json இல்லை.','manifest.json in the zip is not valid JSON.'=>'zip இல் உள்ள manifest.json செல்லுபடியாகும் JSON அல்ல.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json இன் \'%s\' எதிர்பார்க்கப்பட்ட மதிப்புடன் பொருந்தவில்லை.','Another installation is running; try again in a moment.'=>'மற்றொரு நிறுவல் இயங்குகிறது; சிறிது நேரத்தில் மீண்டும் முயலவும்.','Not a valid server_build_id: %s'=>'செல்லுபடியாகும் server_build_id அல்ல: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'தொகுப்பு மேனிஃபெஸ்டின் வகை \'%1$s\' கோரப்பட்ட வகை \'%2$s\' உடன் பொருந்தவில்லை.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'தொகுப்பின் text domain \'%1$s\' இந்தத் தளத்தில் உள்ள கூறின் நகலுடன் (\'%2$s\') பொருந்தவில்லை, எனவே நிறுவப்படவில்லை.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'கொடுக்கப்பட்ட டொமைன் \'%1$s\' தொகுப்பு மேனிஃபெஸ்டின் சொந்த ஸ்லக் \'%2$s\' உடனும் அதன் text_domain \'%3$s\' உடனும் பொருந்தவில்லை.','Unsafe slug: %s'=>'பாதுகாப்பற்ற ஸ்லக்: %s','Unsafe text_domain: %s'=>'பாதுகாப்பற்ற text_domain: %s','The package has no %s for its own text domain.'=>'தொகுப்பில் அதன் சொந்த உரை டொமைனுக்கான %s இல்லை.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json காணப்படவில்லை அல்லது அதில் தவறான \'%s\' உள்ளது.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json காணப்படவில்லை அல்லது அதில் தவறான \'entries\' உள்ளது.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json காணப்படவில்லை அல்லது அதில் தவறான \'files\' உள்ளது.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json காணப்படவில்லை அல்லது அதில் தவறான \'extra_domains\' உள்ளது.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json காணப்படவில்லை அல்லது அதில் தவறான \'build_no\' உள்ளது.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json இல் உள்ள \'server_build_id\' சரியான பில்ட் ஐடி அல்ல.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json இல் உள்ள \'contract\' சரியான பதிப்புச் சரம் அல்ல.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json இல் உள்ள \'status\' மதிப்பு \'published\' ஆக இருக்க வேண்டும்.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json இல் உள்ள \'kind\' மதிப்பு \'plugin\' அல்லது \'theme\' ஆக இருக்க வேண்டும்.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json இல் தவறான \'default_domain_entries\' உள்ளது.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json இல் தவறான \'default_domain_files\' உள்ளது.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest காணப்படவில்லை அல்லது அதில் தவறான \'%s\' உள்ளது.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest இல் உள்ள \'server_build_id\' சரியான பில்ட் ஐடி அல்ல.','No record for %s'=>'%s க்கான பதிவு எதுவும் இல்லை','One or more served files no longer match the manifest.'=>'வழங்கப்படும் ஒன்று அல்லது அதற்கு மேற்பட்ட கோப்புகள் இனி மேனிஃபெஸ்ட்டுடன் பொருந்தவில்லை.','No previous build to roll back to.'=>'முந்தைய நிலைக்கு மீட்டமைக்க முந்தைய பில்ட் எதுவும் இல்லை.','The change could not be recorded in the translation index; please try again.'=>'மாற்றத்தை மொழிபெயர்ப்பு அட்டவணையில் பதிவு செய்ய முடியவில்லை; மீண்டும் முயற்சிக்கவும்.','Unknown kind: %s'=>'அறியப்படாத வகை: %s','Unsafe domain: %s'=>'பாதுகாப்பற்ற டொமைன்: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'உரை டொமைன் \'%1$s\' (%2$s) ஏற்கனவே நிறுவப்பட்ட மற்றொரு கூறுக்காக (%3$s) வழங்கப்படுகிறது; எதுவும் நிறுவப்படவில்லை.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'முந்தைய நிலைக்கு மீட்டமைத்தால் \'%1$s\' (%2$s) மேலெழுதப்படும்; அது இப்போது நிறுவப்பட்ட மற்றொரு கூறுக்காக (%3$s) வழங்கப்படுகிறது; எதுவும் மாற்றப்படவில்லை.','Zip is missing expected file: %s'=>'எதிர்பார்க்கப்பட்ட கோப்பு zip இல் இல்லை: %s','sha256 mismatch for %s'=>'%s க்கான sha256 பொருந்தவில்லை','The package declares no main translation file.'=>'தொகுப்பு முதன்மை மொழிபெயர்ப்புக் கோப்பை அறிவிக்கவில்லை.','Zip is missing expected default file: %s'=>'எதிர்பார்க்கப்பட்ட இயல்பிருப்புக் கோப்பு zip இல் இல்லை: %s','sha256 mismatch for default/%s'=>'default/%s க்கான sha256 பொருந்தவில்லை','Could not stage %s'=>'%s ஐ ஸ்டேஜ் செய்ய முடியவில்லை','Could not stage default/%s'=>'default/%s ஐ ஸ்டேஜ் செய்ய முடியவில்லை','Entry count mismatch for %s'=>'%s க்கான உள்ளீடுகளின் எண்ணிக்கை பொருந்தவில்லை','Could not verify entry count for %s'=>'%s க்கான உள்ளீடுகளின் எண்ணிக்கையைச் சரிபார்க்க முடியவில்லை','l10n.php entry count mismatch for %s'=>'%s க்கான l10n.php உள்ளீடுகளின் எண்ணிக்கை பொருந்தவில்லை','Default supplement entry count mismatch.'=>'இயல்பிருப்பு துணைப்பகுதி உள்ளீடுகளின் எண்ணிக்கை பொருந்தவில்லை.','The package produced no servable main translation file.'=>'தொகுப்பு வழங்கக்கூடிய முதன்மை மொழிபெயர்ப்புக் கோப்பை உருவாக்கவில்லை.','Could not prepare %s for rollback.'=>'%s ஐ முந்தைய நிலைக்கு மீட்டமைக்கத் தயார் செய்ய முடியவில்லை.','Could not back up %s before replacing it.'=>'%s ஐ மாற்றுவதற்கு முன் காப்புப்பிரதி எடுக்க முடியவில்லை.','Could not move %s into place.'=>'%s ஐ உரிய இடத்திற்கு நகர்த்த முடியவில்லை.','English (United States)'=>'ஆங்கிலம் (அமெரிக்க ஐக்கிய நாடுகள்)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest கிடைக்கவில்லை: %s','could not read _manifest.json: %s'=>'_manifest.json ஐப் படிக்க முடியவில்லை: %s','failed to parse _manifest.json: %s'=>'_manifest.json ஐ பகுப்பாய்வு செய்ய முடியவில்லை: %s','_manifest.json has an unexpected structure'=>'_manifest.json எதிர்பாராத கட்டமைப்பைக் கொண்டுள்ளது','Could not create the package archive.'=>'தொகுப்புக் காப்பகத்தை உருவாக்க முடியவில்லை.','No writable temporary directory is available for packaging.'=>'தொகுப்பதற்கு எழுதக்கூடிய தற்காலிக கோப்பகம் எதுவும் இல்லை.','A file in the component could not be read, so it was not packaged.'=>'கூறில் உள்ள ஒரு கோப்பைப் படிக்க முடியவில்லை, எனவே அது தொகுக்கப்படவில்லை.','Only plugins and themes can be packaged.'=>'செருகுநிரல்களையும் தீம்களையும் மட்டுமே தொகுக்க முடியும்.','The component\'s main file was not found.'=>'கூறின் முதன்மைக் கோப்பு கிடைக்கவில்லை.','The component is not inside the plugins or themes directory.'=>'கூறு செருகுநிரல்கள் அல்லது தீம்கள் கோப்பகத்தில் இல்லை.','Babilim ran out of time for this step and will continue on the next check.'=>'இந்தப் படிக்கு Babilim க்கு நேரம் போதவில்லை; அடுத்த சரிபார்ப்பில் தொடரும்.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim இந்தத் தளத்தைச் சரிபார்க்க முடியவில்லை, எனவே சரிபார்ப்பு வெற்றிபெறும் வரை எதுவும் பதிவிறக்கமோ நிறுவலோ செய்யப்படாது.','Registration response was missing required fields.'=>'பதிவு பதிலில் தேவையான புலங்கள் இல்லை.','No pending challenge to verify.'=>'சரிபார்க்க நிலுவையில் உள்ள சவால் எதுவும் இல்லை.','Verify response was missing site_token.'=>'சரிபார்ப்பு பதிலில் site_token இல்லை.','No site id is on file to rotate a token for.'=>'டோக்கனை மாற்றுவதற்கான தள அடையாளம் எதுவும் பதிவில் இல்லை.','Rotate-token response was missing site_token.'=>'டோக்கன் மாற்ற பதிலில் site_token இல்லை.','nonce must be a hexadecimal string.'=>'nonce ஒரு ஹெக்சாடெசிமல் சரமாக இருக்க வேண்டும்.','No pending challenge for this nonce.'=>'இந்த nonce க்கு நிலுவையில் உள்ள சவால் எதுவும் இல்லை.','Too many requests.'=>'அதிகமான கோரிக்கைகள்.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'இந்தத் தளத்தில் %2$d மொழிகளில் %1$d கூறுகள் உள்ளன; இதற்கு %3$d சரிபார்ப்புத் தொகுதிகள் தேவை; Babilim ஒரு முறைக்கு அதிகபட்சம் %4$d ஐக் கையாளும். அமைப்புகளில் நிர்வகிக்கப்படும் மொழிகளைக் குறைக்கவும் அல்லது பயன்படுத்தாத செருகுநிரல்கள் மற்றும் தீம்களை முடக்கவும், பின்னர் இப்போது மீண்டும் சரிபார் என்பதை அழுத்தவும்.','Babilim could not finish checking this site.'=>'Babilim இந்தத் தளத்தைச் சரிபார்த்து முடிக்க முடியவில்லை.','This site\'s address is too long for Babilim to register.'=>'இந்தத் தளத்தின் முகவரி Babilim பதிவு செய்ய முடியாத அளவு நீளமாக உள்ளது.','This site\'s locale code is not one Babilim can register.'=>'இந்தத் தளத்தின் மொழிக் குறியீட்டை Babilim பதிவு செய்ய முடியாது.','The download response was missing a usable location.'=>'பதிவிறக்க பதிலில் பயன்படுத்தக்கூடிய இருப்பிடம் இல்லை.','The service\'s upload offer was incomplete.'=>'சேவை வழங்கிய பதிவேற்ற விவரங்கள் முழுமையாக இல்லை.','This component is larger than the service accepts, so it cannot be uploaded.'=>'இந்தக் கூறு சேவை ஏற்கும் அளவை விடப் பெரியது, எனவே பதிவேற்ற முடியாது.','The packaged component could not be read.'=>'தொகுக்கப்பட்ட கூறைப் படிக்க முடியவில்லை.','A part of the upload kept failing, so the upload was cancelled.'=>'பதிவேற்றத்தின் ஒரு பகுதி தொடர்ந்து தோல்வியடைந்ததால் பதிவேற்றம் ரத்து செய்யப்பட்டது.','Could not read: %s'=>'படிக்க முடியவில்லை: %s']];